package dev.recipeeditor.exporters;

import java.nio.file.*;
import java.util.*;
import java.util.concurrent.TimeUnit;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import static org.junit.jupiter.api.Assertions.*;

final class ExportManifestTest {
    @TempDir Path root;
    @Test void profileAndManifestRoundTripIncludingHashes()throws Exception {final var f=new ExportFixtures(root);final var p=f.plan(List.of(f.create("test:new",f.raw)),ExportFormat.DATAPACK);final var store=new ExportMetadataStore();store.saveProfile(f.project,p.request().context().profile());store.commit(f.project,p.request().context().profile(),f.manifest(p));final var loaded=store.load(f.project);assertEquals(List.of(p.request().context().profile()),loaded.profiles());assertEquals(List.of(f.manifest(p)),loaded.manifests());Files.writeString(store.path(f.project),Files.readString(store.path(f.project)).replace("GENERATED_RUNTIME_UNVERIFIED","FAKE"));assertThrows(java.io.IOException.class,()->store.load(f.project));}
    @Test void reexportUsesStableFilesAndProtectsUserEdits()throws Exception {final var f=new ExportFixtures(root);final var c=f.create("test:new",f.raw);final var p=f.plan(List.of(c),ExportFormat.DATAPACK);try(final var service=new RecipeExportService(f.planner)){final var result=service.export(p,x->{}).result().get(10,TimeUnit.SECONDS);assertEquals(ExportResult.Status.SUCCESS,result.status(),result.diagnostics().toString());final var workspace=service.workspace(f.project).get(10,TimeUnit.SECONDS);final var ctx=f.context(List.of(c),List.of(),ExportFormat.DATAPACK,Map.of(),workspace.manifests(),OverwritePolicy.OWNED_UNCHANGED);final var next=service.dryRun(f.request(ctx)).get(10,TimeUnit.SECONDS);assertTrue(next.valid());assertEquals(p.files().keySet(),next.files().keySet());assertEquals(ExportResult.Status.SUCCESS,service.export(next,x->{}).result().get(10,TimeUnit.SECONDS).status());assertEquals(1,service.workspace(f.project).get(10,TimeUnit.SECONDS).manifests().size());final var file=f.target.resolve(p.files().keySet().iterator().next());Files.writeString(file,"user edited");assertFalse(service.dryRun(f.request(ctx)).get(10,TimeUnit.SECONDS).valid());assertEquals(ExportResult.Status.FAILED,service.export(next,x->{}).result().get(10,TimeUnit.SECONDS).status());assertEquals("user edited",Files.readString(file));}}
    @Test void staleFilesAreRemovedOnlyIfOwnedAndUnchanged()throws Exception {final var f=new ExportFixtures(root);final var old=f.plan(List.of(f.create("test:old",f.raw)),ExportFormat.DATAPACK);new ExportFileWriter().write(old,new ExportControl(),x->{},()->{});final var ctx=f.context(List.of(f.create("test:new",f.raw)),List.of(),ExportFormat.DATAPACK,Map.of(),List.of(f.manifest(old)),OverwritePolicy.OWNED_UNCHANGED);final var p=f.planner.plan(f.request(ctx));assertTrue(p.valid());new ExportFileWriter().write(p,new ExportControl(),x->{},()->{});for(final var stale:p.obsoleteFiles())assertFalse(Files.exists(f.target.resolve(stale)));assertTrue(Files.exists(f.target.resolve("datapacks/recipe_editor_testprofile/data/test/recipes/new.json")));}
    @Test void staleUserModifiedFileBlocksCleanup()throws Exception {final var f=new ExportFixtures(root);final var old=f.plan(List.of(f.create("test:old",f.raw)),ExportFormat.DATAPACK);new ExportFileWriter().write(old,new ExportControl(),x->{},()->{});final var stale=f.target.resolve("datapacks/recipe_editor_testprofile/data/test/recipes/old.json");Files.writeString(stale,"user");final var ctx=f.context(List.of(f.create("test:new",f.raw)),List.of(),ExportFormat.DATAPACK,Map.of(),List.of(f.manifest(old)),OverwritePolicy.OWNED_UNCHANGED);assertFalse(f.planner.plan(f.request(ctx)).valid());assertEquals("user",Files.readString(stale));}
    @Test void refusePolicyBlocksChangedOwnedFiles()throws Exception {final var f=new ExportFixtures(root);final var old=f.plan(List.of(f.create("test:new",f.raw)),ExportFormat.DATAPACK);new ExportFileWriter().write(old,new ExportControl(),x->{},()->{});final var ctx=f.context(List.of(f.create("test:new",f.raw.replace("\"count\":2","\"count\":3"))),List.of(),ExportFormat.DATAPACK,Map.of(),List.of(f.manifest(old)),OverwritePolicy.REFUSE);assertFalse(f.planner.plan(f.request(ctx)).valid());}
}
